/* Sounds recorded from real apps and embedded here, so nothing has to be downloaded and they work offline.
   faceid : the soft chime heard when Face ID is accepted. Plays on a successful login, Face ID unlock and when data is saved.
   follow : the quick double tick heard on an Instagram Follow tap. Plays on Add income, Add expense, Debt buttons and Settings.
   Source clips (WAV, mono, 44.1 kHz) are cut from the screen recordings with no processing apart from short fades. */
window.MBT_SOUNDS={
  faceid:"data:audio/wav;base64,",
  follow:"data:audio/wav;base64,"
};
